"""Original, bounded readings of selected positions in the 236-item catalogue.

Catalogue membership is not a claim that every work in a grouped entry is covered.
Spiritual excerpts are resolved only through the separately verified registry.
"""

def reading(key, title, author, scope, paragraphs, quote, reflection, task,
            sources, art, art_note, music, music_note):
    return dict(slug=key, catalogue=key, title=title, author=author, scope=scope,
                paragraphs=paragraphs, quote=quote,
                reflection='Комментарий мастерской: ' + reflection,
                task=task, sources=sources, source=sources[0][0],
                source_label=sources[0][1], art=art, art_note=art_note,
                music=music, music_note=music_note)


